insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009401501','40000000-0000-4000-8000-000000940150','Delimite o problema','O caso trata de aplicações de derivadas; leia o que é observável antes de escolher uma implementação.',1),('70000000-0000-4000-8000-000009401502','40000000-0000-4000-8000-000000940150','Recupere o princípio','Extremos e taxas exigem interpretar derivadas junto com domínio e condições do problema.',2),('70000000-0000-4000-8000-000009401503','40000000-0000-4000-8000-000000940150','Aplique ao cenário','Modele a grandeza, localize candidatos e aplique o teste pertinente.',3),('70000000-0000-4000-8000-000009401504','40000000-0000-4000-8000-000000940150','Elimine as alternativas','As demais alternativas confundem níveis de abstração, responsabilidade de componentes ou uma consequência que não decorre dos dados.',4),('70000000-0000-4000-8000-000009401505','40000000-0000-4000-8000-000000940150','Verifique a conclusão','Valide sinal, unidades e os limites do contexto. Portanto, a resposta é: Domínio e unidades coerentes..',5);
